  // spellchecker: ignore-next-line
  @@index([shipping_carrier_primary, shipping_carrier_secondary], map: "shopping_mall_platform_configurations_shipping_carrier_f3330740")
  // spellchecker: ignore-next-line
  @@index([password_complexity_min_length, password_complexity_require_uppercase, password_complexity_require_lowercase, password_complexity_require_numbers, password_complexity_require_symbols], map: "shopping_mall_platform_configurations_password_complex_b58d7cc1")
