  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  orderShipment shopping_mall_order_shipments @relation(fields: [shopping_mall_order_shipment_id], references: [id], onDelete: Cascade, map: "shopping_mall_shipping_trackings_shopping_mall_order_s_52320f05")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_order_shipment_id], map: "shopping_mall_shipping_trackings_shopping_mall_order_s_99c1fe10")
  @@index([tracking_number(ops: raw("gin_trgm_ops"))], type: Gin)
}

