  @@index([shopping_mall_order_shipment_id, created_at], map: "shopping_mall_delivery_events_shopping_mall_order_ship_33e9ae73")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_order_shipment_id, status], map: "shopping_mall_delivery_events_shopping_mall_order_ship_1f09fbff")
  @@index([notes(ops: raw("gin_trgm_ops"))], type: Gin)
