export async function test_api_product_sales_statistics_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // Create admin connection and authenticate
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: "https://example.com/admin/join",
      referrer: "https://example.com/admin/signup",
    } satisfies IShoppingMallAdmin.IJoin,
  });

  // Create seller connection and authenticate
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      business_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      createdAt: new Date().toISOString(),
    } satisfies IShoppingMallSeller.IJoin,
  });

  // Create a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 8,
        }),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 8,
          sentenceMax: 15,
          wordMin: 3,
          wordMax: 7,
        }),
        categoryId: typia.random<string & tags.Format<"uuid">>(),
        price: typia.random<
          number & tags.Minimum<0.01> & tags.Maximum<10000>
        >(),
        sku: RandomGenerator.alphaNumeric(10),
        images: [typia.random<string & tags.Format<"uri">>()],
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Create a product variant for the product
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
        body: {
          attributes: "{}",
          price: typia.random<
            number & tags.Minimum<0.01> & tags.Maximum<10000>
          >(),
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<100>
          >(),
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);

  // Use admin connection to retrieve sales statistics for the product
  const salesStats =
    await api.functional.shoppingMall.admin.products.sales_stats.index(
      adminConnection,
      {
        productId: product.id,
      },
    );
  typia.assert(salesStats);

  // Verify sales stats is a number and represents valid financial data
  TestValidator.predicate(
    "sales statistics is a valid number",
    typeof salesStats === "number" && salesStats >= 0,
  );
  TestValidator.predicate(
    "sales statistics represents realistic revenue (at least one order)",
    salesStats > 0 && salesStats <= 1000000,
  );
  TestValidator.predicate(
    "sales statistics matches expected order value",
    salesStats >= variant.price,
  );
}

