    await generate_random_shopping_mall_admin_product_variants_attributes_create(
      adminConnection,
      {
        body: {
          name: RandomGenerator.name(),
          description: RandomGenerator.paragraph(),
          type: "string",
        } satisfies IShoppingMallProductVariantAttribute.ICreate,
      },
