  const activeLarge =
    await generate_random_shopping_mall_admin_product_variants_attribute_values_create(
      adminConnection,
      {
        body: {
          attribute_type_id: attribute2.id,
          name: "Large",
        } satisfies IShoppingMallVariantAttributeValue.ICreate,
