import type { IShoppingMallProductVariantIRequestIAttributes } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariantIRequestIAttributes";
import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
export async function test_api_product_variants_search_by_admin(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Authenticate as administrator using the utility function
  const adminConnection: api.IConnection = { host: connection.host };
  const admin: IShoppingMallAdmin.IAuthorized = await authorize_admin_join(
    adminConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        href: "https://example.com/admin/join",
        referrer: "https://example.com/admin/signup",
      } satisfies IShoppingMallAdmin.IJoin,
    },
  );
  typia.assert(admin);
  // Step 2: Create search request with filtering criteria
  const searchRequest: IShoppingMallProductVariant.IRequest = {
    page: 1,
    limit: 10,
    price_min: 100,
    price_max: 1000,
    availability: "available",
    attributes: "color:red,size:large", // Correct: string type per schema, format example from system design
    search: "product",
  } satisfies IShoppingMallProductVariant.IRequest;
  // Step 3: Call the admin product variants search endpoint with adminConnection
  const response: IPageIShoppingMallProductVariant.ISummary =
    await api.functional.shoppingMall.admin.products.skus.index(
      adminConnection,
      {
        body: searchRequest,
      },
    );
  typia.assert(response);
  // Step 4: Validate pagination structure
  TestValidator.equals(
    "pagination current page is 1",
    response.pagination.current,
    1,
  );
  TestValidator.equals("pagination limit is 10", response.pagination.limit, 10);
  TestValidator.predicate(
    "pagination records is positive",
    response.pagination.records > 0,
  );
  TestValidator.predicate(
    "pagination pages is positive",
    response.pagination.pages > 0,
  );
  // Step 5: Validate that data array contains items
  TestValidator.predicate("data array is not empty", response.data.length > 0);
  // Step 6: Validate that all returned variants match search criteria
  for (const variant of response.data) {
    // Verify price is within range
    TestValidator.predicate(
      "variant price is within range",
      variant.price >= 100 && variant.price <= 1000,
    );
    // Verify availability status is 'available'
    TestValidator.equals(
      "variant availability status is available",
      variant.availability_status,
      "available",
    );
    // Verify inventory level is positive (for 'available')
    TestValidator.predicate(
      "variant inventory level is positive",
      variant.inventory_level > 0,
    );
    // Verify name contains search term
    if (searchRequest.search) {
      TestValidator.predicate(
        "variant name contains search term",
        variant.name.toLowerCase().includes(searchRequest.search.toLowerCase()),
      );
    }
    // Verify variation_attributes have correct structure
    TestValidator.predicate(
      "variation_attributes is an array",
      Array.isArray(variant.variation_attributes),
    );
    for (const attr of variant.variation_attributes) {
      TestValidator.predicate(
        "each attribute has string representation",
        typeof attr === "string",
      );
    }
    // Verify images have correct structure
    TestValidator.predicate(
      "images is an array",
      Array.isArray(variant.images),
    );
    for (const image of variant.images) {
      TestValidator.equals("image id is uuid", typeof image.id, "string");
      TestValidator.equals("image url is uri", typeof image.url, "string");
      TestValidator.equals("image name is string", typeof image.name, "string");
      TestValidator.equals(
        "image extension is string",
        typeof image.extension,
        "string",
      );
      TestValidator.predicate(
        "image order is integer",
        Number.isInteger(image.order),
      );
      TestValidator.equals(
        "image is_primary is boolean",
        typeof image.is_primary,
        "boolean",
      );
      TestValidator.equals(
        "image created_at is date-time",
        typeof image.created_at,
        "string",
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";
import api from "@ORGANIZATION/PROJECT-api";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IShoppingMallVariantSkus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallVariantSkus";
export async function test_api_product_variant_retrieval_success(
  connection: api.IConnection,
): Promise<void> {
  // Generate a random product variant with proper formatting
  const variant: IShoppingMallVariantSkus =
    typia.random<IShoppingMallVariantSkus>();
  // Ensure is_active is true for successful retrieval
  variant.is_active = true;
  // Ensure stock_quantity is positive (required for availability)
  variant.stock_quantity = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();
  // Ensure price is positive
  variant.price = typia.random<number & tags.Minimum<0>>();
  // Ensure availability_status is set to in_stock (when stock_quantity > 0)
  variant.availability_status = "in_stock";
  // Generate a proper SKU formatted as PRDSKU-XXXXXXXX
  const prefix = "PRDSKU-";
  const suffix = typia.random<string & tags.Pattern<"^[0-9A-Za-z]{8}$">>();
  const properSku = prefix + suffix;
  variant.sku = properSku;
  // Ensure all UUID fields are properly formatted
  variant.product_id = typia.random<string & tags.Format<"uuid">>();
  variant.variant_id = typia.random<string & tags.Format<"uuid">>();
  variant.category_id = typia.random<string & tags.Format<"uuid">>() ?? null;
  variant.brand_id = typia.random<string & tags.Format<"uuid">>() ?? null;
  variant.seller_id = typia.random<string & tags.Format<"uuid">>() ?? null;
  // Ensure created_at and updated_at are ISO format
  variant.created_at = new Date().toISOString();
  variant.updated_at = new Date().toISOString();
  // Since we have no variant creation endpoint, we'll retrieve the variant by its SKU
  // This assumes the system already has this variant (simulated by typia.random)
  const retrievedVariant: IShoppingMallVariantSkus =
    await api.functional.shoppingMall.products.skus.at(connection, {
      skuId: variant.sku,
    });
  // Validate the complete structure of the response
  typia.assert(retrievedVariant);
  // Perform business logic validation without type checking (since typia.assert() already validated types)
  TestValidator.equals("SKU matches", retrievedVariant.sku, variant.sku);
  TestValidator.equals(
    "is_active status is true",
    retrievedVariant.is_active,
    true,
  );
  TestValidator.predicate(
    "stock_quantity is positive",
    retrievedVariant.stock_quantity > 0,
  );
  TestValidator.equals(
    "availability_status is in_stock",
    retrievedVariant.availability_status,
    "in_stock",
  );
  TestValidator.predicate("price is positive", retrievedVariant.price > 0);
}

