    await api.functional.shoppingMall.admin.payment_surcharge_rules.update(
      adminConnection,
      {
        ruleId,
        body: {
          paymentMethod,
          region,
          applicableFrom,
          surchargePercentage,
          is_active,
        } satisfies IShoppingMallPaymentSurchargeRule.IUpdate,
      },
    );
