        body: {
          message: event.reason,
        },
      },
    );
  }
  // Step 7: Retrieve compliance history
  const complianceHistory =
    await api.functional.shoppingMall.admin.sellers.compliance_history.index(
      adminConnection,
      {
        sellerId: seller.id,
      },
    );
  typia.assert(complianceHistory);
  // Step 8: Validate compliance history data structure and content
  TestValidator.equals(
    "pagination is correct",
    complianceHistory.pagination.current,
    0,
  );
  TestValidator.equals(
    "limit is correct",
    complianceHistory.pagination.limit,
    30,
  );
  TestValidator.equals(
    "total records match evidence",
    complianceHistory.pagination.records,
    complianceEvents.length,
  );
  TestValidator.equals(
    "total pages is appropriate",
    complianceHistory.pagination.pages,
    1,
  );
  TestValidator.equals(
    "data is an array of compliance history objects",
    Array.isArray(complianceHistory.data),
    true,
  );
  TestValidator.equals(
    "data length matches event count",
    complianceHistory.data.length,
    complianceEvents.length,
  );
  // Step 9: Validate chronological order of events
  // Events should be ordered by created_at in ascending order (oldest first)
  // Since we created events from oldest to newest, they should be returned in that order
  for (let i = 0; i < complianceHistory.data.length; i++) {
    const storedEvent = complianceHistory.data[i];
    const expectedEvent = complianceEvents[i];
    TestValidator.equals(
      `event ${i} type matches`,
      storedEvent.event_type,
      expectedEvent.event_type,
    );
    TestValidator.equals(
      `event ${i} status matches`,
      storedEvent.status,
      expectedEvent.status,
    );
    TestValidator.equals(
      `event ${i} reason matches`,
      storedEvent.reason,
      expectedEvent.reason,
    );
    // Validate timestamps match (within 1ms tolerance due to processing time)
    const storedTime = new Date(storedEvent.created_at).getTime();
    const expectedTime = new Date(expectedEvent.created_at).getTime();
    TestValidator.predicate(
      `event ${i} timestamp is correct`,
      Math.abs(storedTime - expectedTime) < 1000,
    );
  }
  // Step 10: Verify all events are in the list and no extra events
  const retrievedEventTypes = complianceHistory.data.map(
    (event) => event.event_type,
  );
  const expectedEventTypes = complianceEvents.map((event) => event.event_type);
  TestValidator.equals(
    "all event types are present",
    retrievedEventTypes.join(","),
    expectedEventTypes.join(","),
  );
  TestValidator.predicate(
    "no unexpected events",
    retrievedEventTypes.length === expectedEventTypes.length,
  );
}

