export async function test_api_audit_log_retrieval_by_admin(
  connection: api.IConnection,
): Promise<void> {
  // Create admin connection and authenticate
  const adminConnection: api.IConnection = { host: connection.host };
  const admin: IShoppingMallAdmin.IAuthorized = await authorize_admin_join(
    adminConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.IJoin,
    },
  );
  typia.assert(admin);
  // We assume the system generates an audit log upon admin join
  // Wait briefly to ensure log is generated
  await new Promise((resolve) => setTimeout(resolve, 500));
  // Construct request with appropriate filtering parameters
  // Note: IShoppingMallAuditLog is a string type - we cannot validate contents
  // But we can validate that the request structure is correct and system responds properly
  const request: IShoppingMallAuditLog.IRequest = {
    start_date: new Date(Date.now() - 60000).toISOString(), // last minute
    end_date: new Date().toISOString(), // now
    user_id: admin.id,
    severity_level: "high",
    compliance_category: "access_control", // From schema examples - likely to be present
    page: 1,
    limit: 25,
  } satisfies IShoppingMallAuditLog.IRequest;
  // Call the API with admin connection (connection isolation pattern)
  const response: IPageIShoppingMallAuditLog =
    await api.functional.shoppingMall.audit.logs.index(adminConnection, {
      body: request,
    });
  typia.assert(response);
  // Validate response structure
  TestValidator.equals(
    "pagination current page matches request",
    response.pagination.current,
    request.page,
  );
  TestValidator.equals(
    "pagination limit matches request",
    response.pagination.limit,
    request.limit,
  );
  TestValidator.predicate(
    "pagination records > 0",
    () => response.pagination.records > 0,
  );
  TestValidator.predicate(
    "pagination pages >= 1",
    () => response.pagination.pages >= 1,
  );
  TestValidator.predicate("has audit logs", () => response.data.length > 0);
  TestValidator.predicate("data items are strings", () =>
    response.data.every((item) => typeof item === "string"),
  );
  // Verify non-admin users cannot access audit logs
  const unauthorizedConnection: api.IConnection = { host: connection.host };
  // We don't log in - this connection has no auth
  await TestValidator.error(
    "unauthorized user cannot access audit logs",
    async () => {
      await api.functional.shoppingMall.audit.logs.index(
        unauthorizedConnection,
        {
          body: request,
        },
      );
    },
  );
}

