  for (let i = 0; i < severityValues.length - 1; i++) {
    if (severityValues[i] !== severityValues[i + 1]) {
      // Ensure ascending order: low < medium < high < critical
      const priorityOrder = { low: 0, medium: 1, high: 2, critical: 3 };
      TestValidator.predicate(
